import { defineConfig, type UserConfig } from "@hey-api/openapi-ts";

type Plugins = NonNullable<UserConfig["plugins"]>;

const job = (input: string, path: string, sdk: Plugins = []): UserConfig => ({
  input,
  output: {
    path,
    postProcess: ["oxfmt"],
    // The bundled client runtime is not written for exactOptionalPropertyTypes; its exported types still check callers.
    header: [
      "// This file is auto-generated by @hey-api/openapi-ts",
      ...(sdk.length > 0 ? ["// @ts-nocheck"] : []),
    ],
  },
  plugins: [
    ...sdk,
    {
      name: "zod",
      requests: false,
      responses: false,
      comments: false,
      dates: { local: true, offset: true },
      $resolvers: {
        number(ctx) {
          // MCP carries JSON numbers; reject precision loss instead of coercing to bigint.
          return ctx.schema.format === "int64"
            ? ctx.$(ctx.plugin.imports.z).attr("number").call().attr("int").call()
            : undefined;
        },
        object(ctx) {
          if (ctx.nodes.additionalProperties(ctx) === undefined) {
            // Preserve fields added by Garmin without weakening the documented fields.
            const properties = ctx.nodes.shape(ctx);
            ctx.nodes.base = () => ctx.$(ctx.plugin.imports.z).attr("looseObject").call(properties);
          }
        },
        unknown(ctx) {
          return ctx.$(ctx.plugin.imports.z).attr("json").call();
        },
      },
    },
  ],
});

// Typed fetch SDK; TrainingClient supplies the fetch, timeout, redirect, and response checks.
const sdk = (baseUrl: string | boolean = true): Plugins => [
  "@hey-api/typescript",
  { name: "@hey-api/client-fetch", baseUrl },
  "@hey-api/sdk",
];

export default defineConfig([
  job("../docs/garmin-personal-openapi.json", "../src/garmin-api/personal"),
  // Downloaded from https://apis.garmin.com/tools/apiDocs/training-api-workouts.
  // Its server URL ends in /workout, but its paths (/workout, /schedule) are relative to /training-api.
  job(
    "../docs/garmin-training-openapi.json",
    "../src/garmin-api/training",
    sdk("https://apis.garmin.com/training-api"),
  ),
  // Downloaded from https://apis.garmin.com/tools/apiDocs/user-api.
  job("../docs/garmin-user-openapi.json", "../src/garmin-api/user", sdk()),
  // Downloaded from https://apis.garmin.com/tools/apiDocs/wellness-api.
  job("../docs/garmin-wellness-openapi.json", "../src/garmin-api/wellness", sdk()),
]);
